style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
html,
body,
#container-main,
.content {
    background: transparent !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-image: url("https://LINK-DE-TU-IMAGEN.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: -9999;
}

/* Hace que las tarjetas sean un poco transparentes */
section,
.card,
.game-card,
.container,
.content {
    background: rgba(20, 20, 20, 0.45) !important;
    backdrop-filter: blur(5px);
    border-radius: 12px;
}
}
